WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, item.product_id, item.qty, item.price FROM (SELECT id, customer_id, created_at, coupon_codes, EXPLODE_OUTER(items) AS item FROM carts) t) SELECT CASE WHEN qty >= 5 THEN 'HIGH' ELSE 'LOW' END AS qty_tier, ROUND(AVG(product_id), 2) AS avg_product_id, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids FROM lines GROUP BY CASE WHEN qty >= 5 THEN 'HIGH' ELSE 'LOW' END;
